// dlb-oracles.mjs — parse/encode the "oracles" DLB member (fortune-cookie Oracle hints)
//
// Format (makedefs do_oracles / src/rumors.c init_oracles+outoracle):
//   line0: raw Dont_Edit_Data header  "#\tThis data file is generated by 'makedefs'.  Do not edit. \n"  (NOT xcrypt'd)
//   line1: "%5d\n" = oracle_cnt  (number of oracle blocks incl. the special one at index 0)
//   then (oracle_cnt + 1) offset lines, each exactly "%05lx\n" (6 bytes) = ABSOLUTE byte offsets.
//        offs[i]   = first content byte of block i (i.e. the byte just after that block's "---\n" separator)
//        offs[cnt] = EOF (unused by the reader; makedefs writes it, init_oracles ignores it)
//   text section (starts at txt_offset = len(line0)+len(line1)+(cnt+1)*6):
//        "---\n" <block0 content> "---\n" <block1 content> ... "---\n"   (trailing separator, then EOF)
//   Each content line is xcrypt'd SEPARATELY (bitmask resets per line, like rumors/bogusmon).
//   Reader fseeks to offs[idx], reads lines until it hits a literal "---\n".
//
// So block i content bytes = buf[offs[i] : offs[i+1]-4]   (the 4 = the "---\n" that terminates it).
//
// parseOracles(buf) -> { header:Buffer(line0 incl \n), cnt, blocks: string[][] (decrypted lines, no \n) }
// encodeOracles({header, blocks}) -> Buffer  (recomputes cnt/offsets; re-xcrypts each line)

import { readDlb, writeDlb, xcrypt } from './dlb.mjs';

const NL = 0x0a;
const SEP = Buffer.from('---\n');

function splitLines(buf) {
  const out = [];
  let s = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === NL) { out.push(buf.slice(s, i)); s = i + 1; }
  }
  if (s < buf.length) out.push(buf.slice(s));
  return out;
}

export function parseOracles(buf) {
  const nl = 0x0a;
  let p = 0;
  function readline() { const s = p; while (p < buf.length && buf[p] !== nl) p++; const ln = buf.slice(s, p); p++; return ln; }
  const l0 = readline();                       // header (content, sans \n)
  const header = buf.slice(0, p);              // header incl \n
  const l1 = readline();
  const cnt = parseInt(l1.toString('ascii').trim(), 10);
  if (!(cnt > 0)) throw new Error('bad oracle count: ' + JSON.stringify(l1.toString()));
  const offs = [];
  for (let i = 0; i < cnt + 1; i++) offs.push(parseInt(readline().toString('ascii').trim(), 16));
  const txtOffset = p;
  // sanity: block0 content starts 4 bytes (one "---\n") after txt_offset
  if (offs[0] !== txtOffset + 4) {
    throw new Error(`offs[0]=${offs[0]} != txtOffset+4=${txtOffset + 4}`);
  }
  const blocks = [];
  for (let i = 0; i < cnt; i++) {
    const content = buf.slice(offs[i], offs[i + 1] - 4); // strip trailing "---\n"
    // verify the 4 bytes we stripped really are the separator
    const sep = buf.slice(offs[i + 1] - 4, offs[i + 1]);
    if (!sep.equals(SEP)) throw new Error(`block ${i}: expected "---\\n" before offs[${i + 1}], got ${JSON.stringify(sep.toString())}`);
    const lines = splitLines(content).map((b) => xcrypt(Buffer.from(b)).toString('utf8'));
    blocks.push(lines);
  }
  return { header, cnt, blocks, offs, txtOffset };
}

export function encodeOracles({ header, blocks }) {
  const cnt = blocks.length;
  // header size = len(header) + len(count line) + (cnt+1) offset lines (6 bytes each)
  const countLine = Buffer.from(String(cnt).padStart(5, ' ') + '\n', 'ascii'); // "%5d\n"
  const headerBytes = header.length + countLine.length + (cnt + 1) * 6;
  const txtOffset = headerBytes;

  // Build text section and record absolute content-start offsets.
  const parts = [];
  const offs = [];
  let pos = txtOffset;
  for (let i = 0; i < cnt; i++) {
    parts.push(SEP); pos += 4;             // "---\n" separator
    offs.push(pos);                        // content start of block i
    for (const line of blocks[i]) {
      const enc = xcrypt(Buffer.from(line + '\n', 'utf8'));
      parts.push(enc); pos += enc.length;
    }
  }
  parts.push(SEP); pos += 4;               // trailing separator
  offs.push(pos);                          // EOF offset
  const textSection = Buffer.concat(parts);

  // Header offset lines
  const offLines = Buffer.concat(offs.map((o) => Buffer.from(o.toString(16).padStart(5, '0') + '\n', 'ascii')));
  return Buffer.concat([header, countLine, offLines, textSection]);
}

// CLI
if (process.argv[1] && process.argv[1].replace(/\\/g, '/').endsWith('dlb-oracles.mjs')) {
  const [cmd, path = 'sys/wasm/nhdat'] = process.argv.slice(2);
  const r = readDlb(path);
  const m = r.entries.find((x) => x.fname === 'oracles');
  if (cmd === 'roundtrip') {
    const parsed = parseOracles(m.data);
    const re = encodeOracles(parsed);
    console.log('orig size:', m.data.length, 'reencoded:', re.length, 'byte-identical:', re.equals(m.data));
    if (!re.equals(m.data)) {
      for (let i = 0; i < Math.min(re.length, m.data.length); i++) {
        if (re[i] !== m.data[i]) { console.log('first diff at byte', i, 'orig', m.data[i], 're', re[i]); break; }
      }
    }
  } else if (cmd === 'dump') {
    const parsed = parseOracles(m.data);
    console.log('cnt:', parsed.cnt);
    parsed.blocks.forEach((b, i) => { console.log(`\n=== BLOCK ${i} (${b.length} lines) ===`); console.log(b.join('\n')); });
  } else {
    console.log('usage: dlb-oracles.mjs [roundtrip|dump] [nhdat-path]');
  }
}
